function backupManifest(row){try{return JSON.parse(row?.manifest_json||"{}")}catch{return{}}}
function backupBytes(n){n=Number(n||0);if(!n)return"—";const u=["B","KB","MB","GB"],i=Math.min(Math.floor(Math.log(n)/Math.log(1024)),u.length-1);return (n/Math.pow(1024,i)).toFixed(i?1:0)+" "+u[i]}
function backupStatus(row){if(row?.status==="completed")return'<span class="status-chip active">'+t("תקין","Healthy")+'</span>';if(row?.status==="failed")return'<span class="status-chip declined">'+t("נכשל","Failed")+'</span>';return'<span class="status-chip pending">'+t("בתהליך","Running")+'</span>'}
async function renderBackups(root){
 const archive=await api("/api/admin/backups/archive-status"),d=archive.status||{},current=archive.current||null,previous=archive.previous||null,verify=archive.verify||{};
 const pill=d.status==="success"?'<span class="status-chip active">'+t("תקין","Healthy")+'</span>':d.status==="failed"?'<span class="status-chip declined">'+t("הגיבוי האחרון נכשל","Last backup failed")+'</span>':'<span class="status-chip pending">'+t("טרם הושלם","Not completed yet")+'</span>';
 const verifyPill=verify.status==="success"?'<span class="status-chip active">'+t("בדיקת ארכיון תקינה","Archive verified")+'</span>':verify.status==="failed"?'<span class="status-chip declined">'+t("בדיקת הארכיון נכשלה","Archive verification failed")+'</span>':'<span class="status-chip pending">'+t("טרם נבדק","Not yet verified")+'</span>';
 const card=(title,item,slot)=>{if(!item)return'<article class="dashboard-empty"><strong>'+title+'</strong><p>'+t("עדיין אין גיבוי שמור במיקום הזה.","No backup is stored in this slot yet.")+'</p></article>';return'<article class="dashboard-row"><div><strong>'+title+'</strong><p>'+esc(fmt(item.updated_at))+' · '+esc(backupBytes(item.size))+'</p><small>SHA-256 <code>'+esc(String(item.sha256||"").slice(0,16))+'…</code> · Git <code>'+esc(String(item.git_sha||"").slice(0,8))+'</code></small></div><div>'+t("ארכיון ZIP מלא","Full ZIP archive")+'</div><div class="dashboard-row-actions"><a class="button button-primary button-small" href="/api/admin/backups/archive/'+slot+'" download>'+t("הורד תיקיית גיבוי (ZIP)","Download backup folder (ZIP)")+'</a></div></article>'};
 const workflow="https://github.com/nh8030954-art/gmach-karov1/actions/workflows/full-production-backup.yml",verifyWorkflow="https://github.com/nh8030954-art/gmach-karov1/actions/workflows/verify-full-backup.yml";
 root.innerHTML='<div class="dashboard-section"><div class="section-heading"><div><h3>'+t("גיבוי מלא של האתר","Full site backup")+'</h3><p>'+t("כמו בשמחים בשמחתם: Database מלא, כל קבצי R2, קוד האתר והיסטוריית Git נארזים ל־ZIP פרטי ב־R2. נשמרים רק CURRENT ו־PREVIOUS.","Like Smachim: full database, all R2 files, site code and Git history are packed into a private ZIP in R2. Only CURRENT and PREVIOUS are retained.")+'</p></div><div class="dashboard-row-actions">'+pill+verifyPill+'</div></div><div class="stats-grid" style="margin-block:16px"><article><span>'+t("גיבוי מוצלח אחרון","Last successful backup")+'</span><strong style="font-size:1rem">'+esc(d.last_success_at?fmt(d.last_success_at):"—")+'</strong></article><article><span>'+t("ניסיון אחרון","Last attempt")+'</span><strong style="font-size:1rem">'+esc(d.last_attempt_at?fmt(d.last_attempt_at):"—")+'</strong></article><article><span>'+t("שמירה","Retention")+'</span><strong style="font-size:1rem">CURRENT + PREVIOUS</strong></article><article><span>'+t("תזמון","Schedule")+'</span><strong style="font-size:1rem">'+t("יומי 00:30 UTC","Daily 00:30 UTC")+'</strong></article></div><div class="dashboard-row-actions" style="margin-bottom:16px"><a target="_blank" rel="noopener" class="button button-primary" href="'+workflow+'">'+t("צור גיבוי עכשיו","Create backup now")+'</a><a target="_blank" rel="noopener" class="button button-secondary" href="'+verifyWorkflow+'">'+t("בדוק גיבוי עכשיו","Verify backup now")+'</a><button class="button button-secondary" id="admin-backup-refresh" type="button">'+t("רענון","Refresh")+'</button></div><p class="dashboard-note">'+t("יצירה ובדיקה ידנית נפתחות ב־GitHub Actions המאובטח, בדיוק כמו בשמחים בשמחתם. אין מפתחות R2 או Cloudflare בדפדפן.","Manual creation and verification open the secured GitHub Actions workflow, just like Smachim. No R2 or Cloudflare credentials are exposed to the browser.")+'</p><div style="display:grid;gap:12px;margin-top:16px">'+card("CURRENT — "+t("הגיבוי המוצלח האחרון","Latest successful backup"),current,"current")+card("PREVIOUS — "+t("הגיבוי המוצלח שלפניו","Previous successful backup"),previous,"previous")+'</div><div class="dashboard-note" style="margin-top:14px"><strong>'+t("מה כלול","Included")+':</strong> D1 SQL · R2 media · dist/worker/migrations · Git snapshot + bundle · wrangler configuration · SHA256SUMS. '+t("סודות מערכת אינם נשמרים בארכיון. שחזור Production אינו אוטומטי.","System secret values are excluded. Production restore is never automatic.")+'</div></div>';
 $("#admin-backup-refresh",root).onclick=()=>renderBackups(root);
}
